/**
 *
 * DialogPositioner is a full-screen container that positions the dialog popup using flexbox.
 *
 * [Live Demo](https://www.primereact.org/dialog/)
 *
 * @module DialogPositioner
 * @group components
 *
 */
import type { ComponentInstance } from '@primereact/types/core';
import type { BaseComponentProps, PassThroughType } from '../..';
import type { DialogRootInstance } from './DialogRoot.types';
/**
 * Defines passthrough(pt) options type in DialogPositioner component.
 */
export type DialogPositionerPassThroughType<E> = PassThroughType<DialogPositionerInstance, E>;
/**
 * Defines passthrough(pt) options of DialogPositioner component.
 */
export interface DialogPositionerPassThrough {
    /**
     * Used to pass attributes to the root's DOM element.
     */
    root?: DialogPositionerPassThroughType<React.HTMLAttributes<HTMLDivElement>>;
}
/**
 * Defines valid properties in DialogPositioner component.
 */
export interface DialogPositionerProps extends BaseComponentProps<DialogPositionerInstance, unknown, DialogPositionerPassThrough> {
}
/**
 * Defines valid state in DialogPositioner component.
 */
export interface DialogPositionerState {
}
/**
 * Defines the methods and properties exposed by DialogPositioner component.
 */
export interface DialogPositionerExposes {
    /**
     * The Dialog component instance.
     */
    dialog: DialogRootInstance | undefined | null;
}
/**
 * Instance of DialogPositioner component.
 */
export type DialogPositionerInstance = ComponentInstance<DialogPositionerProps, DialogPositionerState, DialogPositionerExposes>;
